groups=[('OSC',r(0,6)+[30]),('SUB FM NOISE',r(7,12)),('FILTER',r(16,19)+[115]),('FILTER ENV',r(22,25)),('AMP ENV',r(26,29)),('LFO1',r(13,15)),('LFO2',r(45,47)),('MOD',r(48,59)),('VOICE',[20,21,120,144]),('OUTPUT',[32,121]),('CRUSH',[33,34]),('AUTOPAN',[35,36]),('REVERB',r(37,40)),('DELAY',r(41,44)+[137,138]),('PHASER',r(116,119)),('COMP MASTER',[122,125,128,131,134]),('COMP RV IN',[123,126,129,132,135]),('COMP RV WET',[124,127,130,133,136]),('ARP',r(60,66)+[139,147]),('SEQ PITCH',r(67,82)),('SEQ OCT',r(83,98)),('SEQ GATE',r(99,114)),('PITCH TUNING',[31]+r(140,143)+[148]),('ENV TRACK',[149]),('BANDLIMIT',[145,146])]
