out={'schema':'dnbox-fwui-f7-grouping-proposal/1','status':'PROPOSAL_NOT_APPROVED_NOT_IMPLEMENTED','sourceSchemaCommit':'33d1c0514b51f3391b211d86a8653da5cd6765a3','sourceDescriptorSHA256':hashlib.sha256(source).hexdigest(),'navigation':'PART only: SEL opens existing deep parameter list; its CATEGORIES action opens an index. SELECT browses categories, SEL chooses and returns to first page. SELECT browses four-control pages; K1-4 edit. Existing deep-list ALGORITHM editing and SOUND engine/preset retained. Not wired.','unitQualification':'Metadata is not formatter qualification. Unresolved native physical values must not be replaced with guessed percent/Hz/dB units.','groups':[{'name':n,'pages':[[rows[i] for i in ii[j:j+4]] for j in range(0,len(ii),4)]} for n,ii in groups],'coverage':{'uniqueIds':len(ids),'categories':len(groups),'maxPagesPerCategory':max((len(ii)+3)//4 for n,ii in groups),'totalPages':sum((len(ii)+3)//4 for n,ii in groups)}}
Path('fwui-evidence/f7-proposal/synthone-categories.json').write_text(json.dumps(out,indent=2)+'\n');print(out['coverage'])
